    const val BOOT_LOGO_START = 0xFFFFFFFF.toInt()
    const val BOOT_LOGO_MID = 0xFFE4E4EA.toInt()
    const val BOOT_LOGO_END = 0xFFB9B9C2.toInt()
    const val BOOT_ACCENT = 0xFF3DDC84.toInt()
    const val BOOT_ACCENT_DIM = 0xFF2FAE68.toInt()
    const val BOOT_TEXT = "AppleUX"
    const val BOOT_SUBTEXT = "Designed to feel different"
    const val SOUND_UNLOCK = "appleux_unlock.wav"
    const val SOUND_LOCK = "appleux_lock.wav"
    const val SOUND_CHARGING = "appleux_charge.wav"
    const val SOUND_BOOT = "appleux_boot.wav"
}
